 @Override Map<String,Object> snapshot(ModernSettlementMysqlFixture mysql,String label)throws Exception{
  var core=super.snapshot(mysql,label);for(String db:List.of(A,B)){var c=(Map<String,Object>)core.get(db);c.put("castle_clans",rows(mysql,db,"SELECT clan_id,clan_name,leader_id,leader_name,hascastle,hashouse FROM clan_data ORDER BY clan_id"));c.put("castles",rows(mysql,db,"SELECT castle_id,name,UNIX_TIMESTAMP(war_time) AS war_time,war_duration,war_interval FROM `server_城堡` ORDER BY castle_id"));c.put("weapon_items",rows(mysql,db,"SELECT id,item_id,char_id,count,is_equipped,enchantlvl,durability FROM character_items WHERE item_id=24 ORDER BY id"));}var last=(Map<String,Object>)snapshots.get(snapshots.size()-1);last.put("observed_utc",Instant.now().toString());Files.writeString(root.resolve("snapshots").resolve(label+".json"),json(last),StandardCharsets.UTF_8);save();return core;
 }
 Actor objective(Peer p,int gfx){for(int i=p.received.size()-1;i>=0;i--){byte[] x=p.received.get(i);if((x[0]&255)==Protocol.S_PUT_OBJECT){Actor a=actor(x);if(a.gfx()==gfx)return a;}}return null;}
 int[] position(int x,int y,Set<Long> used){var map=ClassicWorldMapCatalog.forMap(4);for(int dx=-1;dx<=1;dx++)for(int dy=-1;dy<=1;dy++){int px=x+dx,py=y+dy;long key=((long)px<<32)|(py&0xffffffffL);if((dx!=0||dy!=0)&&!used.contains(key)&&map.standingPassable(px,py)&&map.attackPosition(px,py,x,y,1)){used.add(key);return new int[]{px,py};}}throw new AssertionError("retained native standing and melee LOS next to objective absent");}
 @Override void portalFlow(ModernSettlementMysqlFixture mysql)throws Exception{
  start();snapshot(mysql,"before-T26-castle-authentication");
  try(Peer holder=select("CastleHolderA",port,"WireSend",SUN,"SenderA");Peer royal=select("CastleMappedRoyalB",port,"WireRecv",MOON,"RecvB");Peer witness=select("CastleWitnessB",port,"WireMate",MOON,"MateB")){
   beginBattle(royal,witness,"MappedCastleCrown");var entry=portalObserved(royal,"WireRecv(WireMoon)",33051,32337,true,"mapped-royal-normal131-WORLD-entry");long mapped=((Number)((Map<String,Object>)entry.get("self")).get("id")).longValue();require(mapped==0x40000000L,"mapped royal physical10001 held by sourceA");portalObserved(witness,"WireMate(WireMoon)",33051,32337,true,"witness-normal131-WORLD-entry");snapshot(mysql,"after-three-real-C9-and-two-legal131-WORLD-entries");
   Set<Long> used=new HashSet<>();int[] rp=position(33139,32768,used),wp=position(33139,32768,used);portalObserved(royal,"WireRecv(WireMoon)",rp[0],rp[1],false,"mapped-royal-normal-C2E-melee-position");portalObserved(witness,"WireMate(WireMoon)",wp[0],wp[1],false,"witness-normal-C2E-objective-screen");sync(royal);sync(witness);Actor tower=objective(royal,1672);require(tower!=null&&tower.x()==33139&&tower.y()==32768,"actual active-war server-issued Kent tower");evidence.put("actual_castle_tower",actorData(tower));evidence.put("mapped_royal_wire_ID",mapped);snapshot(mysql,"before-normal-physical-attacks-untouched10000HP-tower");
   long until=System.nanoTime()+TimeUnit.SECONDS.toNanos(900);int sum=0;List<Object> attacks=new ArrayList<>();Actor crown=null;
   for(int n=0;n<1500&&crown==null;n++){
    require(System.nanoTime()<until,"bounded normal animation-paced tower combat deadline");long before=System.nanoTime();byte[] request=new Protocol.Writer().c(Protocol.C_ATTACK).d(tower.id()).h(tower.x()).h(tower.y()).bytes();royal.send(request);byte[] own=royal.await(Protocol.S_ATTACK),peer=witness.await(Protocol.S_ATTACK);require(Arrays.equals(own,peer),"same actual mapped attack witnessed by same-source WORLD peer");var ar=new Protocol.Reader(own);ar.c();int action=ar.c();require(ar.d()==mapped&&ar.d()==tower.id(),"attack binds mapped royal and actual tower");int damage=ar.c();ar.c();ar.d();require(ar.remaining()==0,"bounded actual native melee attack");sum+=damage;long cadence=BattleAnimationCatalog.get().requireTimedAction(0,action).durationMillis();require(cadence>0,"retained native animation pace");sync(royal);sync(witness);crown=objective(royal,1482);attacks.add(Map.of("index",n,"sent_utc",Instant.now().toString(),"request_hex",HexFormat.of().formatHex(request),"actual_attack_hex",HexFormat.of().formatHex(own),"damage",damage,"cumulative_wire_damage",sum,"native_animation_cadence_ms",cadence));evidence.put("actual_castle_normal_attacks",attacks);stage="T26-normal-castle-tower-combat";save();long remain=TimeUnit.MILLISECONDS.toNanos(cadence)-(System.nanoTime()-before);if(remain>0)Thread.sleep(Math.max(1,TimeUnit.NANOSECONDS.toMillis(remain)));
   }
   require(crown!=null&&sum>=10000&&sum-((Number)((Map<String,Object>)attacks.get(attacks.size()-1)).get("damage")).intValue()<10000&&crown.x()==tower.x()&&crown.y()==tower.y(),"normal unmodified10000HP tower destruction creates actual crown");evidence.put("actual_castle_generated_crown",actorData(crown));snapshot(mysql,"after-normal-tower-destruction-before-actual-crown-claim");royal.send(new Protocol.Writer().c(Protocol.C_ATTACK).d(crown.id()).h(crown.x()).h(crown.y()).bytes());byte[] owner=royal.await(Protocol.S_CASTLE_OWNER),other=witness.await(Protocol.S_CASTLE_OWNER);require(Arrays.equals(owner,other)&&Arrays.equals(owner,Protocol.castleOwner(1,mapped)),"actual S47 Kent crown owner uses mapped wire ID");sync(royal);sync(witness);require(scalar(mysql,B,"SELECT COUNT(*) FROM clan_data WHERE clan_id=70001 AND leader_id=10001 AND leader_name='RecvB' AND hascastle=1")==1&&scalar(mysql,A,"SELECT COUNT(*) FROM clan_data WHERE hascastle<>0")==0,"actual normal crown saves physical10001 selected sourceB only");evidence.put("actual_mapped_castle_owner_hex",HexFormat.of().formatHex(owner));snapshot(mysql,"after-actual-crown-physical-sourceB-owner-SQL");royal.close();Thread.sleep(500);snapshot(mysql,"after-mapped-royal-normal-QUIT");witness.close();holder.close();
  }
  stop();snapshot(mysql,"after-owned-normal-stop");require(occurrences(serverLog(),"MySQL character disconnect persistence=SUCCESS")==2&&!serverLog().contains("castle ownership SQL rejected"),"two normal WORLD saves and no crown SQL rejection");evidence.put("Java_generations",1);evidence.put("old_TTL_or_clan_matrix_executed",false);evidence.put("product_clock_or_private_phase_changed",false);evidence.put("actual_native_BIN_or_GUI_executed",false);save();
 }
